import React, {
  useEffect,
  useState,
} from "react";
import UsageGraph from "./GraphUsage";
import PokemonBuildPanel from "./buildPanel";

const POKE_PATH =
  "/pokemon_data/";

export default function ComUsage() {
  const [
    pokemonList,
    setPokemonList,
  ] = useState([]);

  const [
    filteredList,
    setFilteredList,
  ] = useState([]);

  const [search, setSearch] =
    useState("");

  const [
    selectedPokemon,
    setSelectedPokemon,
  ] = useState(null);

  const [
    compareList,
    setCompareList,
  ] = useState([]);

  const [
    selectedGen,
    setSelectedGen,
  ] = useState("9");

  const [
    battleMode,
    setBattleMode,
  ] = useState("doubles");

  const [
    clickedBuild,
    setClickedBuild,
  ] = useState(null);

  const normalize = (str) =>
    str
      ?.toLowerCase()
      .replace(
        /[^a-z0-9]/g,
        ""
      ) || "";

  const loadCSV = async (
    path
  ) => {
    const res =
      await fetch(path);
    return await res.text();
  };

  const parseCSV = (
    text
  ) =>
    text
      .trim()
      .split("\n")
      .slice(1)
      .map((r) =>
        r.split(
          /,(?=(?:(?:[^"]*"){2})*[^"]*$)/
        )
      );

  // Load pokemon names
  useEffect(() => {
    const loadPokemonData =
      async () => {
        const text =
          await loadCSV(
            POKE_PATH +
              "pokemon_smogon_names.csv"
          );

        const rows =
          parseCSV(
            text
          );

        const list =
          rows.map(
            (
              row
            ) => ({
              display:
                row[0],
              smogon:
                row[1],
            })
          );

        setPokemonList(
          list
        );
        setFilteredList(
          list
        );
      };

    loadPokemonData();
  }, []);

  // Search filter
  useEffect(() => {
    const filtered =
      pokemonList.filter(
        (p) =>
          normalize(
            p.display
          ).includes(
            normalize(
              search
            )
          )
      );

    setFilteredList(
      filtered
    );

    // Auto-select if only one remains
    if (
      filtered.length ===
      1
    ) {
      setSelectedPokemon(
        filtered[0]
      );
    }
  }, [
    search,
    pokemonList,
  ]);

  const addToCompare =
    () => {
      if (
        selectedPokemon &&
        !compareList.find(
          (p) =>
            p.display ===
            selectedPokemon.display
        )
      ) {
        setCompareList([
          ...compareList,
          selectedPokemon,
        ]);
      }
    };

  const removePokemon =
    (
      name
    ) => {
      setCompareList(
        compareList.filter(
          (p) =>
            p.display !==
            name
        )
      );
    };

  return (
    <div>
      <div
        style={{
          padding:
            "20px",
          background:
            "#f5f5f5",
        }}
      >
        {/* Battle Mode */}
        <label>
          Battle Mode:
        </label>
        <select
          value={
            battleMode
          }
          onChange={(
            e
          ) =>
            setBattleMode(
              e.target
                .value
            )
          }
        >
          <option value="doubles">
            Doubles
          </option>
          <option value="singles">
            Singles
          </option>
        </select>

        <br />
        <br />

        {/* Generation */}
        <label>
          Generation:
        </label>
        <select
          value={
            selectedGen
          }
          onChange={(
            e
          ) =>
            setSelectedGen(
              e.target
                .value
            )
          }
        >
          {[5, 6, 7, 8, 9].map(
            (g) => (
              <option
                key={g}
                value={g}
              >
                Gen {g}
              </option>
            )
          )}
        </select>

        <br />
        <br />

        {/* Search */}
        <input
          type="text"
          value={search}
          onChange={(
            e
          ) =>
            setSearch(
              e.target
                .value
            )
          }
          placeholder="Search Pokémon"
        />

        <br />
        <br />

        {/* Pokemon select */}
        <select
          size="5"
          value={
            selectedPokemon?.display ||
            ""
          }
          onChange={(
            e
          ) =>
            setSelectedPokemon(
              filteredList.find(
                (p) =>
                  p.display ===
                  e.target
                    .value
              )
            )
          }
        >
          {filteredList.map(
            (p) => (
              <option
                key={
                  p.display
                }
                value={
                  p.display
                }
              >
                {
                  p.display
                }
              </option>
            )
          )}
        </select>

        <br />
        <br />

        <button
          onClick={
            addToCompare
          }
        >
          Add to Compare
        </button>

        <hr />

        {/* Compare list with remove buttons */}
        <div>
          {compareList.map(
            (p) => (
              <div
                key={
                  p.display
                }
                style={{
                  display:
                    "flex",
                  alignItems:
                    "center",
                  gap: "10px",
                  marginBottom:
                    "8px",
                }}
              >
                <span>
                  {
                    p.display
                  }
                </span>

                <button
                  onClick={() =>
                    removePokemon(
                      p.display
                    )
                  }
                >
                  X
                </button>
              </div>
            )
          )}
        </div>
      </div>

      <UsageGraph
        compareList={
          compareList
        }
        selectedGen={
          selectedGen
        }
        battleMode={
          battleMode
        }
        onPointClick={
          setClickedBuild
        }
      />

      <PokemonBuildPanel
        clickedBuild={
          clickedBuild
        }
        battleMode={
          battleMode
        }
      />
    </div>
  );
}
